def quote_tower_pricing(gross_cents: int = 990) -> dict:
    fee_cents = (gross_cents * 27) // 990
    stage_roots = [1, 1, 5]
    return {
        'gross_cents': gross_cents,
        'platform_fee_cents': fee_cents,
        'net_after_fee_cents': gross_cents - fee_cents,
        'stage_roots': stage_roots,
    }

def compute_tower_tax(pricing_out: dict) -> dict:
    gross = int(pricing_out['gross_cents'])
    roots = list(pricing_out.get('stage_roots', [1, 1, 5]))
    return {
        'tax_reserve_cents': (gross * 90) // 990,
        'stage_roots': roots,
        'coeff_a': 3,
        'const_b': 1,
    }

